package com.campusvote.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="votes",uniqueConstraints=@UniqueConstraint(columnNames={"student_id","post_id"})) public class Vote { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="student_id") User student; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="post_id") Post post; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="candidate_id") Candidate candidate; LocalDateTime votedAt; public Vote(){} public Vote(User s,Post p,Candidate c){student=s;post=p;candidate=c;votedAt=LocalDateTime.now();} public Long getId(){return id;} public User getStudent(){return student;} public Post getPost(){return post;} public Candidate getCandidate(){return candidate;} }
